// Native private SAM damage/blast probe. Never ship this entry point.
#include "function.h"
#include "campaigndefense.h"
#include <cstdio>
#include <string>
#include <vector>
#include <fstream>
#include "campaignenemies.h"
static int failures;
static void Check(const char* name,bool ok){std::printf("%s %s\n",ok?"PASS":"FAIL",name);std::fflush(stdout);if(!ok)++failures;}
static void Reset(const std::string& dir){Check("load blast fixture",Load_Game((dir+"/fixture.sav").c_str()));Options.Set();GameToPlay=GAME_NORMAL;GameActive=true;PlayerWins=PlayerLoses=false;Frame=100;for(int i=0;i<Triggers.Count();++i)Triggers.Ptr(i)->Action=TriggerClass::ACTION_NONE;for(int i=Units.Count()-1;i>=0;--i)Units.Ptr(i)->Limbo();for(int i=Infantry.Count()-1;i>=0;--i)Infantry.Ptr(i)->Limbo();for(int i=Buildings.Count()-1;i>=0;--i)Buildings.Ptr(i)->Limbo();for(int i=Aircraft.Count()-1;i>=0;--i)Aircraft.Ptr(i)->Limbo();auto good=HouseClass::As_Pointer(HOUSE_GOOD),bad=HouseClass::As_Pointer(HOUSE_BAD);PlayerPtr=good;good->IsHuman=true;bad->IsHuman=false;good->FirepowerBias=bad->FirepowerBias=1;good->Power=bad->Power=1000000;}
static bool Put(TechnoClass* obj,CELL prefer){for(int radius=0;radius<10;++radius)for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){if(MAX(ABS(dx),ABS(dy))!=radius)continue;int x=Cell_X(prefer)+dx,y=Cell_Y(prefer)+dy;if(x<0||x>=MAP_CELL_W||y<0||y>=MAP_CELL_H)continue;CELL cell=XY_Cell(x,y);if(Map.In_Radar(cell)&&obj->Can_Enter_Cell(cell)==MOVE_OK&&obj->Unlimbo(Cell_Coord(cell),DIR_N))return true;}return false;}
static CELL Center(){return XY_Cell(Map.MapCellX+Map.MapCellWidth/2,Map.MapCellY+Map.MapCellHeight/2);}
static BuildingClass* Source(bool player){auto s=new BuildingClass(STRUCT_SAM,player?HOUSE_GOOD:HOUSE_BAD);Check("place SAM away from blast",Put(s,XY_Cell(Map.MapCellX+2,Map.MapCellY+2)));return s;}
static void TickBullets(){std::vector<TARGET> ids;for(int i=0;i<Bullets.Count();++i)ids.push_back(Bullets.Ptr(i)->As_Target());++Frame;for(auto id:ids){auto b=As_Bullet(id);if(b)b->AI();}}
static std::vector<FootClass*> ChainTargets(bool air){std::vector<FootClass*> result;CELL c=Center();for(int i=0;i<4;++i){FootClass* f=air?static_cast<FootClass*>(new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD)):static_cast<FootClass*>(new UnitClass(UNIT_MTANK,HOUSE_BAD));if(air)static_cast<AircraftClass*>(f)->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place separate ricochet target",Put(f,XY_Cell(Cell_X(c)+i*4,Cell_Y(c))));f->Strength=30000;f->IsDiscoveredByPlayer=true;Campaign_Enemies_Mark_Extra(f);result.push_back(f);}return result;}
static void ChainFlight(const std::string& dir,bool air,int saveAfter){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(air);std::vector<int> ids;for(auto f:targets)ids.push_back(air?Aircraft.ID(static_cast<AircraftClass*>(f)):Units.ID(static_cast<UnitClass*>(f)));auto shot=static_cast<TechnoClass*>(sam)->Fire_At(targets[0]->As_Target(),0);Check("start real ricochet missile",shot&&shot->Strength==25);bool saved=false;
 for(int tick=0;tick<2500&&Bullets.Count();++tick){TickBullets();if(saveAfter&& !saved && targets[saveAfter-1]->Strength<30000){Check("save travelling ricochet after native impact",Save_Game((dir+"/chain.sav").c_str(),"TRAVELLING SAM RICOCHET"));Check("reload travelling ricochet",Load_Game((dir+"/chain.sav").c_str()));for(int i=0;i<4;++i)targets[i]=air?static_cast<FootClass*>(Aircraft.Ptr(ids[i])):static_cast<FootClass*>(Units.Ptr(ids[i]));saved=true;}}
 for(int i=0;i<3;++i){std::printf("CHAIN air=%d saveAfter=%d target=%d loss=%d\n",int(air),saveAfter,i,30000-targets[i]->Strength);Check("first target and two distinct ricochets each take one hit",30000-targets[i]->Strength==(air?18:25));}Check("chain stops before fourth target",targets[3]->Strength==30000);Check("all chain missiles finish flight",Bullets.Count()==0);if(saveAfter)Check("requested mid-chain checkpoint was exercised",saved);
}
static void NoSplashBoundary(const std::string& dir,bool outside){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(false);auto primary=targets[0];for(int i=2;i<4;++i)targets[i]->Limbo();auto nearby=targets[1];nearby->Coord=XY_Coord(Coord_X(primary->Coord)+5*ICON_LEPTON_W+(outside?1:0),Coord_Y(primary->Coord));auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(primary->As_Target(),0);Check("start boundary missile",bullet!=nullptr);if(!bullet)return;bullet->Coord=primary->Target_Coord();int before=Bullets.Count();Check("own SAM impact replaces splash path",Campaign_SAM_Chain_Impact(bullet,primary));Check("impact applies damage only to directly hit target",primary->Strength==29975&&nearby->Strength==30000);Check("five-cell boundary includes exact edge and excludes plus one lepton",Bullets.Count()==before+(outside?0:1));if(!outside){BulletClass* bounce=nullptr;for(int i=0;i<Bullets.Count();++i)if(Bullets.Ptr(i)!=bullet)bounce=Bullets.Ptr(i);Check("bounce is real travelling missile to distinct nearby unit",bounce&&bounce->Fuse_Target()==nearby->Target_Coord()&&bounce->Strength==25);}
}
static void Miss(const std::string& dir){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(false);auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(targets[0]->As_Target(),0);bullet->Coord=XY_Coord(Coord_X(targets[0]->Coord),Coord_Y(targets[0]->Coord)+2*ICON_LEPTON_W);int count=Bullets.Count();Check("near miss is handled without splash",Campaign_SAM_Chain_Impact(bullet,targets[0]));Check("near miss deals no damage or bounce",targets[0]->Strength==30000&&Bullets.Count()==count);}
static void Legacy(const std::string& dir){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(false);std::vector<int> ids;for(auto t:targets)ids.push_back(Units.ID(static_cast<UnitClass*>(t)));auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(targets[0]->As_Target(),0);Check("save original travelling missile",bullet&&Save_Game((dir+"/legacy-chain.sav").c_str(),"LEGACY SAM FLIGHT"));{std::ifstream in(dir+"/legacy-chain.sav",std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(in)),{});auto pos=bytes.rfind("CNCCHN01");Check("locate optional chain extension",pos!=std::string::npos);if(pos!=std::string::npos){bytes.resize(pos);std::ofstream out(dir+"/legacy-chain.sav",std::ios::binary|std::ios::trunc);out.write(bytes.data(),bytes.size());}}Check("load old save without chain extension",Load_Game((dir+"/legacy-chain.sav").c_str()));for(int tick=0;tick<2500&&Bullets.Count();++tick)TickBullets();Check("old in-flight SAM receives two-hop behavior without power change",Units.Ptr(ids[0])->Strength==29975&&Units.Ptr(ids[1])->Strength==29975&&Units.Ptr(ids[2])->Strength==29975&&Units.Ptr(ids[3])->Strength==30000);}
static void Scope(const std::string& dir){Reset(dir);auto sam=Source(false);auto target=new UnitClass(UNIT_MTANK,HOUSE_GOOD);Put(target,Center());auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("enemy SAM missile stays stock and does not ricochet",bullet&&bullet->Strength==50&&!Campaign_SAM_Chain_Impact(bullet,target));}
static void Selection(const std::string& dir){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(false);for(int i=2;i<4;++i)targets[i]->Limbo();auto first=targets[0];auto valid=targets[1];auto center=first->Target_Coord();
 for(auto house:{HOUSE_GOOD,HOUSE_JP,HOUSE_NEUTRAL}){if(house==HOUSE_JP){HouseClass::As_Pointer(HOUSE_GOOD)->Make_Ally(house);HouseClass::As_Pointer(house)->Make_Ally(HOUSE_GOOD);}auto excluded=new InfantryClass(INFANTRY_E1,house);Put(excluded,Coord_Cell(first->Coord));excluded->Coord=XY_Coord(Coord_X(center)+ICON_LEPTON_W,Coord_Y(center));excluded->IsDiscoveredByPlayer=true;}
 auto hidden=new UnitClass(UNIT_MTANK,HOUSE_BAD);Put(hidden,Coord_Cell(first->Coord));hidden->Coord=XY_Coord(Coord_X(center)+2*ICON_LEPTON_W,Coord_Y(center));hidden->IsDiscoveredByPlayer=false;
 auto building=new BuildingClass(STRUCT_POWER,HOUSE_BAD);Put(building,Coord_Cell(first->Coord));building->IsDiscoveredByPlayer=true;
 auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(first->As_Target(),0);bullet->Coord=first->Target_Coord();Check("selection impact handled",Campaign_SAM_Chain_Impact(bullet,first));BulletClass* next=nullptr;for(int i=0;i<Bullets.Count();++i)if(Bullets.Ptr(i)!=bullet)next=Bullets.Ptr(i);Check("bounce chooses hostile visible unit instead of closer allied neutral hidden actors or buildings",next&&next->Fuse_Target()==valid->Target_Coord());
 for(int i=Bullets.Count()-1;i>=0;--i)delete Bullets.Ptr(i);auto enemySAM=Source(false);auto plain=static_cast<TechnoClass*>(enemySAM)->Fire_At(first->As_Target(),0);Check("recycled bullet slot cannot inherit a previous chain",plain&&!Campaign_SAM_Chain_Impact(plain,first));
}
static void SourceLost(const std::string& dir){Reset(dir);auto sam=Source(true);auto targets=ChainTargets(false);auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(targets[0]->As_Target(),0);Check("source-loss initial shot exists",bullet!=nullptr);sam->Detach_All();delete sam;for(int tick=0;tick<2500&&Bullets.Count();++tick)TickBullets();Check("launched chain survives firing SAM destruction",targets[0]->Strength==29975&&targets[1]->Strength==29975&&targets[2]->Strength==29975&&targets[3]->Strength==30000);}
static void BeyondFirerRange(const std::string& dir){Reset(dir);auto sam=Source(true);auto center=sam->Center_Coord();auto first=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place first target near firing-range edge",Put(first,Coord_Cell(XY_Coord(Coord_X(center)+44*ICON_LEPTON_W,Coord_Y(center)))));auto next=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place next infantry beyond original SAM range",Put(next,Coord_Cell(XY_Coord(Coord_X(first->Coord)+4*ICON_LEPTON_W,Coord_Y(first->Coord)))));next->Coord=XY_Coord(Coord_X(first->Target_Coord())+4*ICON_LEPTON_W,Coord_Y(first->Target_Coord()));first->IsDiscoveredByPlayer=next->IsDiscoveredByPlayer=true;Check("bounce fixture lies beyond original firing range",!sam->In_Range(next->As_Target(),0));auto bullet=static_cast<TechnoClass*>(sam)->Fire_At(first->As_Target(),0);bullet->Coord=first->Target_Coord();Campaign_SAM_Chain_Impact(bullet,first);BulletClass* bounce=nullptr;for(int i=0;i<Bullets.Count();++i)if(Bullets.Ptr(i)!=bullet)bounce=Bullets.Ptr(i);Check("five-cell ricochet is not clamped to the original firing range",bounce&&bounce->Payback==sam&&Distance(bounce->Fuse_Target(),next->Target_Coord())<=4*ICON_LEPTON_W/3);}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);for(bool air:{false,true})for(int checkpoint:{0,1,2})ChainFlight(dir,air,checkpoint);NoSplashBoundary(dir,false);NoSplashBoundary(dir,true);Miss(dir);Legacy(dir);Selection(dir);SourceLost(dir);BeyondFirerRange(dir);Scope(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
